{
  "lianjing_political_web": {
    "description": "涟京的权力格局并非简单的阵营对抗，而是一个由历史遗留问题、核心利益冲突及政治理念差异交织而成的动态博弈网络。各方势力在不同议题上结盟或对抗，关系流动且复杂。",
    "conflicts_and_alliances": [
      {
        "web_name": "旧制维护者与秩序挑战者",
        "description": "此关系网的核心在于对王朝现有政治与经济秩序的态度。一方是既得利益者，另一方则是变革的推动者，双方的博弈决定了王朝的未来走向。",
        "participating_factions": [
          {
            "faction_name": "苏氏一族",
            "stance": "作为外戚势力的顶峰，其首要目标是巩固并扩大自身在朝堂的影响力，确保家族长盛不衰。对任何可能触及其核心权力（如人事任免、后宫事务）的变革都抱持高度警惕。他们与望族盟在维护旧有阶级利益上有一致性，但亦在争夺最高权力上存在潜在竞争。"
          },
          {
            "faction_name": "望族盟",
            "stance": "代表传统世家门阀的利益，坚决反对任何削弱其经济特权（如田亩、赋税）的改革。他们是“新旧之争”的核心守旧方，会利用其盘根错节的人脉网络，对革新派进行政治阻挠。在对抗革新派时，他们可能会寻求与苏氏一族的合作。"
          },
          {
            "faction_name": "革新派",
            "stance": "由务实的技术官僚组成，认为王朝积弊已深，必须通过激进改革（如新政）方能重焕生机。他们的举措直接挑战了望族盟的根基，是“新旧之争”的核心推动方。为推行新政，他们可能寻求与立场相对开明的清流党在某些议题上合作，以对抗强大的守旧势力。"
          }
        ]
      },
      {
        "web_name": "文官体系的内部制衡",
        "description": "文官集团内部并非铁板一块，清流的道德理想主义与革新派的实用主义，以及他们对军方和内廷的态度，构成了复杂的内部张力。",
        "participating_factions": [
          {
            "faction_name": "清流党",
            "stance": "以维护士大夫的政治伦理和朝堂体面为最高准则。他们对二十年前的“苏林旧怨”耿耿于怀，视其为司法不公与外戚干政的污点，因此在政治上持续对苏氏施压。同时，他们极度厌恶“文武之隙”中军方与宦官的勾结，视之为对文官政治的侵蚀。在这一点上，他们与革新派有共同语言，但又对革新派过于激进的手段持保留意见。"
          },
          {
            "faction_name": "革新派",
            "stance": "他们的关注点在于政策的实际效果。虽然也认同清流党对宦官和武将干政的担忧，但他们的首要敌人是阻碍改革的望族盟。他们愿意与清流党合作打击共同的政敌，但前提是不能影响新政的推行。"
          }
        ]
      },
      {
        "web_name": "禁忌的联合：军方与内廷",
        "description": "在文官政治高度发达的昭晏王朝，军方与宦官的联合被视为对朝堂秩序的严重威胁，这也是连接各方势力的一个关键节点。",
        "participating_factions": [
          {
            "faction_name": "京畿旧部",
            "stance": "作为被边缘化的勋贵武将，他们渴望重获军事上的话语权。为此，他们不惜与内书堂结盟，利用宦官作为通往皇权的捷径，以换取在禁军系统中的实际利益。这个联盟使他们成为整个文官集团（包括清流党和革新派）的共同警惕对象。"
          },
          {
            "faction_name": "内书堂",
            "stance": "作为皇帝的家奴，高淮等宦官的核心利益是巩固自身在内廷的权力和搜刮财富。他们通过扶持京畿旧部来制衡强大的外朝文官势力。同时，他们对所有外朝势力都进行监视，包括苏氏和望族盟，随时准备向皇帝传递不利信息，以求渔翁之利。"
          }
        ]
      }
    ]
  }
}
